snippet_css:
:root{
  --bg: #23372E;
  --fg: #EAD9B8;
  --muted: #CDB893;
  --surface: #2A4034;
  --border: #4E3F2A;
  --accent: #E0B96A;
  --accent-fg: #2B1B10;
  --radius: 5px;
  --radius-sm: 3px;
  --shadow: 0 10px 24px rgba(0,0,0,.45),inset 0 1px 0 rgba(224,185,106,.22);
  --btn-shadow: 0 4px 0 rgba(122,90,34,.9);
  --art-bg: radial-gradient(circle at 50% 45%,#E0B96A 0 16%,#B5883E 17% 24%,#23372E 25%),radial-gradient(circle at 22% 22%,#E0B96A 0 3px,transparent 4px);
  --media-bg: linear-gradient(180deg,#4A2E1F,#2B1B10);
  --cta-bg: #3A2415;
  --input-bg: #1E2E26;
  --ok: #7FA99B;
  --warn: #D98B5F;
  --font-display: 'IM Fell English SC','Noto Serif TC',serif;
  --font-body: 'Libre Caslon Text','Noto Sans TC',serif;
  --font-mono: 'Special Elite',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

